[
  {
    "layers": [{"material": "graphite", "thickness_mm": 10}],
    "rationale": "Exact match to the prior-scored 10mm graphite point (403/[325,325]/18/1, all pass). Zero extrapolation risk on any requirement; areal mass 18 kg/m2 ties the lightest prior record. Included as a guaranteed-safe anchor."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 9}],
    "rationale": "One millimetre below the tested floor. R2 was identical (325K) across 10/20/30mm graphite, so the design is well into a spreading-saturated regime; R1's own conduction term drops with thickness (fitted model gives ~403K, still 17K under 420K). Mass 16.2 kg/m2, 10% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 8}],
    "rationale": "R1 fitted estimate ~402K (17K margin). R2 has shown no sensitivity to thickness over a 3x range at 10-30mm, so a 20% reduction to 8mm should still sit near 325K, 15K under the 340K limit. Mass 14.4 kg/m2, 20% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 7}],
    "rationale": "R1 fitted estimate ~402K. Continuing the same saturated-spreading logic as the 8-9mm points; conductivity (150 W/mK), not thickness, is what set the 325K FE result in the prior sweep. Mass 12.6 kg/m2, 30% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 6}],
    "rationale": "R1 fitted estimate ~401K. This is 40% thinner than any tested graphite point but still above where I'd expect through-thickness conduction to become a meaningful fraction of the total resistance, given R1's model shows only a 4K spread in the entire 10-30mm range. Mass 10.8 kg/m2, 40% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 5}],
    "rationale": "Halves the lightest tested graphite thickness. R1 fitted estimate ~401K (large margin). R2 risk is higher here since we're extrapolating well past tested data, but the flatness from 10-30mm and the 15K raw margin at 10mm give me reasonable confidence this still clears 340K. Mass 9.0 kg/m2, half the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 4}],
    "rationale": "R1 fitted estimate ~401K, comfortably passing. This is the point where I start treating R2 as genuinely uncertain rather than well-supported, but I still judge it more likely than not to pass given the large observed margin and flat thickness trend. Mass 7.2 kg/m2, 60% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 3}],
    "rationale": "R1 fitted estimate ~400K. Near the edge of what I'm willing to call a genuine belief rather than a guess: thickness is a third of the tested minimum. Included because the through-thickness resistance contribution (per R1) is still small at this gauge, suggesting the FE hotspot is unlikely to move far from the 325K baseline. Mass 5.4 kg/m2, 70% below the prior best."
  },
  {
    "layers": [{"material": "graphite", "thickness_mm": 2}],
    "rationale": "R1 fitted estimate ~400K, trivial margin there. This is my most aggressive candidate: a fifth of the tested minimum thickness. I include it because R1's own conduction term is nearly negligible by this gauge, implying the dominant resistances in this problem sit elsewhere and the spreading floor likely lies below 10mm; still, this is the candidate I am least certain of. Mass 3.6 kg/m2, 80% below the prior best."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 10}],
    "rationale": "Exact match to the prior-scored 10mm aluminium point (402/[324,324]/27/1, all pass). Zero extrapolation risk; kept as a material-diverse safe anchor in case graphite behaves differently from aluminium in the FE enclosure model in some way not captured by the isotropic conductivity value given in the brief. Mass 27 kg/m2, heavier than the prior best but fully de-risked."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 6}],
    "rationale": "Aluminium cross-check at a moderate reduction (40% below the tested 10mm floor). R1 fitted estimate ~401K. Provides a second, independently-conductive data point at the same relative thickness reduction as the 6mm graphite candidate, to hedge against any graphite-specific unknown in the FE model. Mass 16.2 kg/m2, 40% below the prior best."
  },
  {
    "layers": [{"material": "aluminium", "thickness_mm": 4}],
    "rationale": "Aluminium cross-check at an aggressive reduction (60% below the tested 10mm floor), same relative thickness cut as the 4mm graphite candidate. R1 fitted estimate ~400K. Aluminium's higher conductivity (200 vs graphite's 150 W/mK) gives it a stronger prior margin on R2 (324K vs 325K at 10mm), which should partially offset the added extrapolation risk at this thickness. Mass 10.8 kg/m2, 60% below the prior best."
  }
]

